def agenda_html():
    """Nine unit cards, each with the slide range it covers"""
    mids = ['m0', 'm1', 'm2', 'm3', 'm4', 'm5', 'm6', 'm7', 'm8']
    starts = [POS[m] for m in mids]
    ends = [x - 1 for x in starts[1:]] + [len(POS)]
    cells = [f'<div style="display:flex;flex-direction:row-reverse;gap:22px;align-items:center;background:{CARD};border:1px solid {LINE};border-radius:20px;padding:20px 28px">'
             f'<p style="font-family:{H};font-size:60px;font-weight:800;line-height:1;color:{C[c][0]};min-width:84px">{i + 1:02d}</p>'
             f'<div style="flex:1;display:flex;flex-direction:column;gap:4px"><h3 style="font-family:{H};font-size:30px;font-weight:600;line-height:1.35;color:{TEXT}">{t(a)}</h3>'
             f'<p style="font-size:24px;line-height:1.4;color:{SOFT}">{t(b)}</p>'
             f'<p style="font-size:24px;font-weight:600;line-height:1.4;color:{C[c][0]}">{t(f"الشرائح من {st} إلى {en}")}</p></div></div>'
             for i, ((a, b, c), st, en) in enumerate(zip(AG, starts, ends))]
    return f'<div style="display:grid;grid-template-columns:repeat(3, 1fr);gap:24px">{"".join(rtl_rows(cells, 3))}</div>', 3 * 176 + 48

