def index_html():
    """The 28 subcomponents by control unit, with the slide each starts on (units 06 and 07 share a column)"""
    def unit(num):
        main = C[MODCOMP[num]][0]
        mid, title, items = MODITEMS[num]
        rows = ''.join(f'<div style="display:flex;flex-direction:row-reverse;align-items:baseline;gap:12px;border-top:1px solid {LINE};padding:5px 0">'
                       f'<p style="font-family:{M};font-size:24px;font-weight:600;line-height:1.35;color:{main};min-width:62px;text-align:right">{c}</p>'
                       f'<p style="flex:1;font-size:24px;line-height:1.35;color:{TEXT}">{t(n)}</p>'
                       f'<p style="font-family:{M};font-size:24px;font-weight:600;line-height:1.35;color:{MUTED}">{POS["i" + c]}</p></div>' for c, n in items)
        h = (f'<div style="display:flex;flex-direction:column;background:{CARD};border:1px solid {LINE};border-radius:16px;overflow:hidden">'
             f'<div style="display:flex;flex-direction:row-reverse;align-items:center;gap:12px;background:{main};padding:10px 20px">'
             f'<p style="font-family:{H};font-size:26px;font-weight:700;line-height:1.3;color:{ON}">{num}</p>'
             f'<p style="flex:1;font-size:24px;font-weight:600;line-height:1.3;color:{ON}">{t(MODNAME[num])}</p>'
             f'<p style="font-size:24px;line-height:1.3;color:{ON}">{t(f"الشريحة {POS[mid]}")}</p></div>'
             f'<div style="display:flex;flex-direction:column;padding:2px 20px 10px">{rows}</div></div>')
        w = (1664 - 2 * 24) / 3 - 40 - 62 - 50 - 24
        return h, 54 + 12 + sum(th(n, 24, w, 1.35, 0.52) + 11 for c, n in items)
    u = {n: unit(n) for n in ('04', '05', '06', '07')}
    col = lambda *ns: f'<div style="flex:1;display:flex;flex-direction:column;gap:20px">{"".join(u[n][0] for n in ns)}</div>'
    h = f'<div style="display:flex;flex-direction:row-reverse;gap:24px;align-items:flex-start">{col("04")}{col("05")}{col("06", "07")}</div>'
    return h, max(u['04'][1], u['05'][1], u['06'][1] + 20 + u['07'][1])

